import backtrader as bt


class BollingerBandsBreakoutStrategy(bt.Strategy):
    params = dict(
        bb_period=20,
        bb_devfactor=2.0,
        take_profit=0.06,
        stop_loss=0.03,
    )

    def __init__(self):
        self.boll = bt.indicators.BollingerBands(
            self.data, period=self.p.bb_period, devfactor=self.p.bb_devfactor
        )
        self.order = None
        self.entry_price = None

    def notify_order(self, order):
        if order.status in (order.Completed, order.Canceled, order.Margin, order.Rejected):
            if order.status == order.Completed:
                if order.isbuy():
                    self.entry_price = order.executed.price
                elif order.issell():
                    self.entry_price = None
            self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.boll.top[0]:
                self.order = self.buy()
        else:
            if self.entry_price is not None:
                if self.data.close[0] >= self.entry_price * (1.0 + self.p.take_profit):
                    self.order = self.close()
                elif self.data.close[0] <= self.entry_price * (1.0 - self.p.stop_loss):
                    self.order = self.close()
